import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('venciendo-las-maldiciones', 'B',
 [dict(t=2220, e=2275, titulo='Un punto de quiebre', txt='¿Cree, y entonces por qué sigue en sus mismas maldiciones? Yo creo que hoy va a ser un punto de quiebre para que usted salga diferente. Cada Santa Cena nos hace salir diferentes, pero esta es crucial, esta es diferente. Esta va a llegar a lo más interno de su corazón, en el alma, y lo va a romper, lo va a destruir, y usted se va a sentir mejor. Hermano, hay mucha gente que se enfrenta con sus fortalezas, pero ahí de adentro están todas sus debilidades, y el Señor hoy se quiere fortalecer en esas debilidades para que usted crezca en el nombre poderoso de Jesús.'),
  dict(t=2640, e=2685, titulo='O cambias ahora o más tarde', txt='[…] y ten cuidado, porque en este tiempo puede ser ya demasiado tarde. O cambias ahorita o vas a cambiar en la gran tribulación. Mire, hermano, yo sé que iglesias no hablan de estos temas, pero aquí yo le tengo que decir la verdad: que si usted y yo no obedecemos a la palabra, nos vamos a quedar.'),
  dict(t=3149, e=3190, titulo='Levántese, restáurese, edifíquese', txt='Su palabra nunca regresa vacía, siempre le trae algo nuevo, y hoy la palabra de Dios está aquí y le está taladrando su corazón para decirle: «No sea gacho, levántese, restáurese, edifíquese. Va a ser usado. La gente se va a asustar cuando hable usted, porque antes hablaba puras charadas».')],
 [dict(t=1980, txt='Hay muchas formas de vencerla, pero una de ellas es la Santa Cena.'),
  dict(t=4620, txt='Hermanos, hay mucho cristiano que no es estable.'),
  dict(t=5237, txt='Vas a conocer la superabundancia desde el día de hoy, porque yo te la desato como profeta.')],
 ['Si cada Santa Cena puede ser un punto de quiebre, ¿qué te gustaría dejar atrás la próxima vez que la tomes?',
  '¿En qué área de tu vida has pedido perdón sin cambiar, y qué paso concreto darías esta semana?',
  '¿Qué tan estable eres cuando las cosas no salen como esperas, y qué te ayudaría a permanecer firme?'])
